#include "request_protocol.h"
#include <string.h>
static int live(AxRequestSlot*s,uint64_t now){if(!s||now==UINT64_MAX)return 0;if((s->phase==AX_REQUEST_ADMITTED||s->phase==AX_REQUEST_DISPATCHED)&&now>=s->deadline)s->phase=AX_REQUEST_EXPIRED;return s->phase==AX_REQUEST_ADMITTED||s->phase==AX_REQUEST_DISPATCHED;}
int ax_request_admit(AxRequestSlot*s,uintptr_t desktop,uintptr_t child,uint64_t epoch,uint64_t deadline,uint64_t now,const unsigned char id[32],size_t size){if(!s||s->phase!=AX_REQUEST_EMPTY||!desktop||!child||!epoch||!id||!size||size>AX_REQUEST_INPUT_CAP||now==UINT64_MAX||deadline<=now)return 0;*s=(AxRequestSlot){.phase=AX_REQUEST_ADMITTED,.desktop=desktop,.child=child,.epoch=epoch,.deadline=deadline};memcpy(s->id,id,32);return 1;}
int ax_request_dispatch(AxRequestSlot*s,uint64_t now){if(!live(s,now)||s->phase!=AX_REQUEST_ADMITTED)return 0;s->phase=AX_REQUEST_DISPATCHED;return 1;}
int ax_request_current(AxRequestSlot*s,uintptr_t child,uint64_t epoch,const unsigned char id[32],uint64_t now){return live(s,now)&&s->phase==AX_REQUEST_DISPATCHED&&s->child==child&&s->epoch==epoch&&id&&!memcmp(id,s->id,32);}
int ax_request_cancel(AxRequestSlot*s,uintptr_t desktop,const unsigned char id[32]){if(!s||!id||s->desktop!=desktop||memcmp(id,s->id,32)||(s->phase!=AX_REQUEST_ADMITTED&&s->phase!=AX_REQUEST_DISPATCHED))return 0;s->phase=AX_REQUEST_CANCELLED;return 1;}
int ax_request_complete(AxRequestSlot*s,uintptr_t child,uint64_t epoch,const unsigned char id[32],uint64_t now,const unsigned char*frame,size_t size){uint32_t status;size_t length;if(!ax_request_current(s,child,epoch,id,now)||!ax_request_response(frame,size,&status,&length))return 0;s->phase=AX_REQUEST_COMPLETED;return 1;}
void ax_request_revoke(AxRequestSlot*s){if(s&&s->phase!=AX_REQUEST_EMPTY&&s->phase!=AX_REQUEST_COMPLETED)s->phase=AX_REQUEST_UNKNOWN;}
int ax_request_id_parse(const char*text,unsigned char out[32]){if(!text||!out||strlen(text)!=64)return 0;for(size_t n=0;n<32;n++){unsigned a=(unsigned char)text[n*2],b=(unsigned char)text[n*2+1];if(!((a>='0'&&a<='9')||(a>='a'&&a<='f'))||!((b>='0'&&b<='9')||(b>='a'&&b<='f')))return 0;out[n]=(unsigned char)(((a<='9'?a-'0':a-'a'+10)<<4)|(b<='9'?b-'0':b-'a'+10));}return 1;}
void ax_request_id_text(const unsigned char in[32],char out[65]){static const char hex[]="0123456789abcdef";for(size_t n=0;n<32;n++){out[2*n]=hex[in[n]>>4];out[2*n+1]=hex[in[n]&15];}out[64]=0;}
int ax_request_response(const unsigned char*frame,size_t size,uint32_t*status,size_t*length){if(!frame||size<8||size>AX_REQUEST_FRAME_CAP||!status||!length)return 0;uint32_t s=0,n=0;for(size_t i=0;i<4;i++){s=(s<<8)|frame[i];n=(n<<8)|frame[4+i];}if(s<100||s>599||n>AX_REQUEST_BODY_CAP||size!=8U+n)return 0;*status=s;*length=n;return 1;}
